import React, { useState, useEffect } from "react";
import { Modal } from "components";
import { useToast } from "components/Toast/ToastContext";
import { useLanguage } from "i18n/LanguageContext";
import { todayDateInputValue } from "./dateUtils";
import { apiPost } from "utils/api";

const inputClass =
  "bg-white-A700 dark:bg-gray-900 border border-surface-border dark:border-gray-700 mt-2 text-gray-900 dark:text-gray-100 text-sm rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 block w-full p-2.5";
const labelClass = "block mb-1 text-sm font-semibold text-gray-800 dark:text-gray-100";

// Records a payment against a party's outstanding balance — a new "payment" row in the
// ledger, not an overwrite of a stored total (see partyLedgerService.addTransaction, which
// also rejects a payment larger than the current balance server-side).
const SettleModal = ({ isOpen, onClose, entry, type, onSettled }) => {
  const toast = useToast();
  const { t } = useLanguage();
  const direction = type === "credit" ? "receivable" : "payable";
  const [amount, setAmount] = useState("");
  const [occurredOn, setOccurredOn] = useState(todayDateInputValue);
  const [note, setNote] = useState("");

  useEffect(() => {
    if (isOpen && entry) {
      setAmount(String(entry.balance));
      setOccurredOn(todayDateInputValue());
      setNote("");
    }
  }, [isOpen, entry]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const pending = Number(entry.balance);
    const amt = Math.min(Number(amount), pending);
    if (amt <= 0) {
      toast.error(t("creditDebit.enterValidAmount"));
      return;
    }
    try {
      await apiPost("/api/parties/transactions", {
        contactId: entry.contact_id,
        direction,
        kind: "payment",
        amount: amt,
        occurredOn,
        note: note || undefined,
      });
      toast.success(t("creditDebit.paymentRecorded"));
      onSettled();
      onClose();
    } catch (error) {
      toast.error(error.message);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={`${t("creditDebit.settle")} — ${entry?.name || ""}`}>
      {entry && (
        <form className="space-y-4" onSubmit={handleSubmit}>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            {t("creditDebit.pending")}:{" "}
            <span className="font-semibold text-gray-800 dark:text-gray-100">
              Rs.{Number(entry.balance).toFixed(2)}
            </span>
          </p>
          <div>
            <label htmlFor="amount_paid" className={labelClass}>
              {t("creditDebit.amount")}
            </label>
            <input
              type="number"
              id="amount_paid"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              className={inputClass}
              min="0.01"
              max={entry.balance}
              step="0.01"
              autoFocus
              required
            />
          </div>
          <div>
            <label htmlFor="settle_date" className={labelClass}>
              {t("creditDebit.date")}
            </label>
            <input
              type="date"
              id="settle_date"
              value={occurredOn}
              onChange={(e) => setOccurredOn(e.target.value)}
              className={inputClass}
              required
            />
          </div>
          <div>
            <label htmlFor="settle_note" className={labelClass}>
              {t("creditDebit.note")} ({t("creditDebit.optional")})
            </label>
            <input
              type="text"
              id="settle_note"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              className={inputClass}
            />
          </div>
          <button
            type="submit"
            className="w-full text-white-A700 bg-primary-600 hover:bg-primary-700 focus:ring-4 focus:outline-none focus:ring-primary-300 font-medium rounded-lg text-sm px-5 py-2.5 text-center transition-colors"
          >
            {t("creditDebit.settle")}
          </button>
        </form>
      )}
    </Modal>
  );
};

export default SettleModal;
